"""Negative-price hours of the fitting period against the model's supply (notes 21.79)."""
import numpy as np, pandas as pd, warnings; warnings.filterwarnings("ignore")
import market1 as M
SP = M.SP; P = np.load(f"{SP}/out/market1n_post.npz"); th = {k: float(np.median(P[k])) for k in M.PN}; R = pd.read_parquet(f"{SP}/out/market1n_rows.parquet"); R = R[R.tr].copy(); kn = np.median(P["kn"], 0); NBC = [f"rl_{c}" for c in ("fr", "nl", "be", "at", "pl", "cz", "ch", "dk")]; R["nb"] = ((R[NBC].values - P["NMU"]) / P["NSD"]) @ kn
R["Dp"] = R.rl - R.other; wd = th["K_s"] * (R.p < -M.EPS) + 0.5 * th["K_s"] * (R.p.abs() <= M.EPS); R["S0"] = M.supply(th, R.p.values, R.L.values, R.co2.values) - wd; R["u"] = R.Dp - R.S0 - R.nb; R["curt"] = R.rlreal - R.rl; R["p0pub"] = M.clear(th, R.Dp.values, R.L.values, R.co2.values, eps=R.nb.values)
print("fitting hours", len(R), "| at or below zero", int((R.p <= M.EPS).sum()), "| below zero", int((R.p < -M.EPS).sum()), "| below -10 EUR", int((R.p < -10).sum()), "| below -50", int((R.p < -50).sum()), "| lowest", round(float(R.p.min()), 1))
B = pd.cut(R.p, [-600, -50, -20, -10, -5, -1, -0.1, 0.1, 5, 15, 30, 60]); T = R.groupby(B).agg(n=("p", "size"), price=("p", "mean"), demand=("Dp", "mean"), model_supply=("S0", "mean"), shift=("u", "mean"), shift_sd=("u", "std"), real_minus_pub=("curt", "mean"), lig=("lig", "mean"), coal=("coal", "mean"), gas=("gasg", "mean"), other=("other", "mean"), imports=("X", "mean"), storage=("S", "mean"), d_l=("d_l", "mean"), d_c=("d_c", "mean"), d_g=("d_g", "mean"), eX=("eX", "mean"), eS=("eS", "mean"), eps=("eps", "mean")); print(T.round(2).T.to_string())
# the curve traced by demand: mean actual price and mean model price (no shift) by demand bin at the low end
Bd = pd.cut(R.Dp - R.nb, [-99, -8, -4, 0, 4, 8, 12, 16, 20]); T2 = R.groupby(Bd).agg(n=("p", "size"), actual=("p", "median"), model=("p0pub", "median"), actual_p10=("p", lambda v: v.quantile(0.1)), model_p10=("p0pub", lambda v: v.quantile(0.1)), actual_p90=("p", lambda v: v.quantile(0.9)), model_p90=("p0pub", lambda v: v.quantile(0.9)), share_neg=("p", lambda v: (v < -M.EPS).mean()), model_share_neg=("p0pub", lambda v: (v < -M.EPS).mean())); print("by demand axis minus neighbour term (GW): actual price against the model's price with no shift, EUR/MWh"); print(T2.round(1).T.to_string())
pg = np.array([30, 15, 5, 1, 0.2, -0.2, -1, -5, -10, -20, -50, -100.0]); Lm, cm = float(R.L[R.p <= 5].median()), float(R.co2[R.p <= 5].median()); s = M.supply(th, pg, np.full_like(pg, Lm), np.full_like(pg, cm)) - th["K_s"] * (pg < 0); print(f"model supply at cost index {Lm:.0f}, GW, at prices", pg.tolist(), ":", np.round(s, 1).tolist())
N = R[R.p < -M.EPS]; b = np.polyfit(N.p, N.u, 1); print("negative-price hours: shift on price, slope GW per EUR", round(b[0], 3), "| in 0..-10:", round(float(np.polyfit(N.p[N.p > -10], N.u[N.p > -10], 1)[0]), 3), "| below -10:", round(float(np.polyfit(N.p[N.p <= -10], N.u[N.p <= -10], 1)[0]), 3), "| corr of real-minus-published with price below zero", round(float(N.curt.corr(N.p)), 2))
R[["p", "Dp", "nb", "S0", "u", "curt", "p0pub", "L", "co2"]].to_parquet(f"{SP}/out/neg_rows.parquet")
